def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    op = [h[1] for h in history]
    opD = op.count('D')
    opC = n - opD
    if opD == n:
        return 'D'
    if n >= 10 and opD >= n - 2:
        return 'D'
    last_me, last_op = history[-1]
    if last_me == 'D' and last_op == 'D' and opC > 0:
        return 'C'
    if last_op == 'D':
        return 'D'
    return 'C'
